import Link from 'next/link';

export default function Forbidden() {
  return (
    <div
      style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontFamily:
          '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        backgroundColor: '#fafafa',
        color: '#111',
      }}
    >
      <div style={{ textAlign: 'center', maxWidth: 420, padding: 24 }}>
        <div
          style={{
            fontSize: 72,
            fontWeight: 700,
            color: '#e53e3e',
            lineHeight: 1,
            marginBottom: 8,
          }}
        >
          403
        </div>
        <h1
          style={{
            fontSize: 24,
            fontWeight: 600,
            margin: '0 0 12px',
          }}
        >
          Forbidden
        </h1>
        <p
          style={{
            fontSize: 16,
            color: '#666',
            margin: '0 0 24px',
            lineHeight: 1.5,
          }}
        >
          You do not have permission to access this page. Please contact an
          administrator if you believe this is a mistake.
        </p>
        <Link
          href="/"
          style={{
            display: 'inline-block',
            padding: '10px 24px',
            backgroundColor: '#111',
            color: '#fff',
            borderRadius: 6,
            textDecoration: 'none',
            fontSize: 14,
            fontWeight: 500,
          }}
        >
          Return Home
        </Link>
      </div>
    </div>
  );
}

